#!/usr/bin/env python3
"""Render codec and TTS timing reports without hand-entered figures."""
import json,statistics
from pathlib import Path
def aggregate(rows):
 values=[v for row in rows for v in row["raw_latency_ms"]]; ordered=sorted(values); median=statistics.median(ordered); p95=ordered[max(0,int(.95*len(ordered))-1)]
 durations=[row["audio_duration_seconds"] for row in rows for _ in row["raw_latency_ms"]]; rtfs=[v/(d*1000) for row in rows for v,d in zip(row["raw_latency_ms"],[row["audio_duration_seconds"]]*len(row["raw_latency_ms"]))]
 return {"n_trials":len(values),"latency_ms_median":median,"latency_ms_p95":p95,"realtime_factor_median":statistics.median(rtfs),"audio_seconds_per_second":1/statistics.median(rtfs)}
def main():
 root=Path("experiments/results/latency_benchmark"); codec=json.loads((root/"codec.json").read_text()); tts=json.loads((root/"tts.json").read_text()); summary={"schema_version":1,"hardware":codec["hardware"],"codec":{},"tts":{}}
 for condition in sorted({x["condition"] for x in codec["conditions"]}):
  summary["codec"][condition]={stage:aggregate([x for x in codec["conditions"] if x["condition"]==condition and x["stage"]==stage]) for stage in ("encode","decode","end_to_end")}
 for row in tts["conditions"]: summary["tts"][f"{row['chunk_ms']}ms"]={"output_token_budget":row["output_token_budget"],"emitted_valid_tokens":row["emitted_valid_tokens"],"generation":row["generation"],"generation_and_decode":row["generation_and_decode"]}
 (root/"summary.json").write_text(json.dumps(summary,indent=2)+"\n",encoding="utf-8",newline="\n")
 lines=["# Latency and throughput benchmark","",f"Hardware: `{summary['hardware'].get('device_name',summary['hardware']['device_type'])}`; float32, batch one. This is synchronized batch/chunk simulation, not production streaming.","","## Codec","","| Input | Stage | Median latency | p95 latency | Median RTF | Audio seconds / wall second |","|---|---|---:|---:|---:|---:|"]
 for condition,stages in summary["codec"].items():
  for stage,row in stages.items(): lines.append(f"| {condition} | {stage} | {row['latency_ms_median']:.2f} ms | {row['latency_ms_p95']:.2f} ms | {row['realtime_factor_median']:.4f} | {row['audio_seconds_per_second']:.1f} |")
 lines += ["","## Parallel TTS","","| Output budget | Stage | Median latency | p95 latency | Median RTF | Emitted valid tokens |","|---|---|---:|---:|---:|---:|"]
 for condition,data in summary["tts"].items():
  for key,label in (("generation","generation"),("generation_and_decode","generation + waveform decode")):
   row=data[key]; lines.append(f"| {condition} | {label} | {row['latency_ms_median']:.2f} ms | {row['latency_ms_p95']:.2f} ms | {row['realtime_factor_median']:.4f} | {data['emitted_valid_tokens']} |")
 lines += ["","RTF below 1 is faster than real time only on the documented hardware. The preregistered conversational reference additionally requires sub-300 ms p95 end-to-end chunk latency.","","Generated by `scripts/summarize_latency_benchmarks.py`."]
 (root/"REPORT.md").write_text("\n".join(lines)+"\n",encoding="utf-8",newline="\n"); print(json.dumps(summary,indent=2))
if __name__=="__main__": main()
